// Soft Utility Style Tokens - Scaffold
import type { StyleTokens } from "./tokens";

export const softUtilityTokens: StyleTokens = {
  "border": {
    "width": "border",
    "color": "border-[#2d5b63]",
    "radius": "rounded-lg",
    "style": "border-solid"
  },
  "shadow": {
    "sm": "shadow-sm",
    "md": "shadow-md",
    "lg": "shadow-lg",
    "none": "shadow-none",
    "hover": "hover:shadow-md",
    "focus": "focus:shadow-md"
  },
  "interaction": {
    "transition": "transition-all duration-200",
    "hoverOpacity": "hover:opacity-90",
    "active": "active:scale-[0.98]"
  },
  "typography": {
    "heading": "font-semibold tracking-tight",
    "body": "font-sans",
    "sizes": {
      "hero": "text-4xl md:text-6xl",
      "h1": "text-3xl md:text-5xl",
      "h2": "text-2xl md:text-3xl",
      "h3": "text-xl md:text-2xl",
      "body": "text-sm md:text-base",
      "small": "text-xs md:text-sm"
    }
  },
  "spacing": {
    "section": "py-10 md:py-20",
    "container": "px-4 md:px-8",
    "card": "p-5 md:p-6",
    "gap": {
      "sm": "gap-2 md:gap-4",
      "md": "gap-4 md:gap-6",
      "lg": "gap-6 md:gap-8"
    }
  },
  "colors": {
    "background": {
      "primary": "bg-[#f4f8f6]",
      "secondary": "bg-[#2d5b63]",
      "accent": [
        "bg-[#a9d8cc]",
        "bg-[#f3c98b]",
        "bg-[#e6b7b0]",
        "bg-[#b8c9ed]"
      ]
    },
    "text": {
      "primary": "text-[#2d5b63]",
      "secondary": "text-[#a9d8cc]",
      "muted": "text-zinc-500"
    },
    "button": {
      "primary": "bg-[#2d5b63] text-white",
      "secondary": "bg-[#f4f8f6] text-[#2d5b63]",
      "danger": "bg-red-500 text-white"
    }
  },
  "forbidden": {
    "classes": [],
    "patterns": [],
    "reasons": {}
  },
  "required": {
    "button": [
      "rounded-lg",
      "border",
      "font-medium",
      "inline-flex",
      "items-center"
    ],
    "card": [
      "rounded-lg",
      "border",
      "bg-white/80"
    ],
    "input": [
      "rounded-lg",
      "border",
      "bg-background",
      "focus:outline-none"
    ]
  }
};

// Soft Utility Component Recipes
import {
  sizeParam,
  fullWidthParam,
  buttonSlots,
  cardSlots,
  inputSlots,
  variant,
  createStyleRecipes,
} from "./factory";

export const softUtilityRecipes = createStyleRecipes("soft-utility", "Soft Utility", {
  button: {
    id: "button",
    name: "Button",
    nameZh: "按钮",
    description: "Soft Utility style button",
    skeleton: {
      element: "button",
      baseClasses: [
        "font-medium",
        "rounded-lg",
        "border border-[#2d5b63]",
        "transition-all duration-200",
      ],
    },
    parameters: [
      sizeParam({ sm: "px-3 py-1.5 text-sm", md: "px-5 py-2.5 text-base", lg: "px-7 py-3.5 text-lg" }),
      fullWidthParam,
    ],
    variants: {
      primary: variant("primary", "Primary", "主要", [
        "bg-[#2d5b63] text-white",
      ]),
      secondary: variant("secondary", "Secondary", "次要", [
        "bg-[#f4f8f6] text-[#2d5b63]",
      ]),
      outline: variant("outline", "Outline", "轮廓", [
        "bg-transparent text-[#2d5b63]",
      ]),
    },
    slots: buttonSlots("Click"),
    states: {
      hover: ["hover:opacity-90"],
      active: ["active:scale-[0.97]"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },

  card: {
    id: "card",
    name: "Card",
    nameZh: "卡片",
    description: "Soft Utility style card",
    skeleton: {
      element: "div",
      baseClasses: [
        "bg-[#f4f8f6]",
        "border border-[#2d5b63]/20",
        "rounded-lg",
        "overflow-hidden",
        "transition-all duration-200",
      ],
    },
    parameters: [
      {
        id: "padding",
        label: "Padding",
        labelZh: "内边距",
        type: "select",
        options: [
          { value: "sm", label: "Small", labelZh: "小", classes: "p-3" },
          { value: "md", label: "Medium", labelZh: "中", classes: "p-5" },
          { value: "lg", label: "Large", labelZh: "大", classes: "p-8" },
        ],
        default: "md",
      },
    ],
    variants: {
      default: variant("default", "Default", "默认", [
        "shadow-md",
      ]),
      outlined: variant("outlined", "Outlined", "描边", [
        "border-[#2d5b63]/40",
      ]),
    },
    slots: cardSlots("Card Title", "Card content goes here."),
    states: {
      hover: ["hover:shadow-lg"],
    },
  },

  input: {
    id: "input",
    name: "Input",
    nameZh: "输入框",
    description: "Soft Utility style input",
    skeleton: {
      element: "input",
      baseClasses: [
        "w-full",
        "bg-[#f4f8f6]",
        "border border-[#2d5b63]/30",
        "rounded-lg",
        "text-[#2d5b63]",
        "font-normal",
        "placeholder:text-[#2d5b63]/40",
        "focus:outline-none",
        "transition-all duration-200",
      ],
    },
    parameters: [
      sizeParam({ sm: "px-3 py-2 text-sm", md: "px-4 py-2.5 text-base", lg: "px-5 py-3.5 text-lg" }),
    ],
    variants: {
      default: variant("default", "Default", "默认", []),
    },
    slots: inputSlots("Type here..."),
    states: {
      focus: ["focus:border-[#2d5b63]", "focus:ring-1 focus:ring-[#2d5b63]/30"],
      disabled: ["opacity-50 cursor-not-allowed"],
    },
  },
});

